Consider the following statements:
```cpp
int *p;
int i, k;
i = 142;
k = i;
p = &i;
```
Which of the following statements changes the value of i to 143?
(i) k = 143;
(ii) *k = 143;
(iii) p = 143;
(iv) *p = 143;

What is the output of the following code?
```cpp
#include <iostream.h>
class A {
public:
    void f() {
        std::cout << "A::f" << std::endl;
    }
    virtual void g() {
        std::cout << "A::g" << std::endl;
    }
};

class B : public A {
public:
    void f() {
        std::cout << "B::f" << std::endl;
    }
    virtual void g() {
        std::cout << "B::g" << std::endl;
    }
};

int main(int argc, char** argv) {
    A a; B b;
    A* aPtr = &a;
    A* bPtr = &b;
    aPtr->f();
    aPtr->g();
    bPtr->f();
    bPtr->g();
    return 0;
}
```
Is there anything to be noticed? Explain it.
